from .base_cl_tool import BaseClToolInterface


class BackhaulParamsInterface(BaseClToolInterface):
    """Keyword for Backhaul Params related commands."""

    def get_backhaul_params(self, timeout='5min', flags=None, **kwargs):
        """
        Get AC non-operator owned backhaul parameters.

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = flags.replace(' ', '').split(',') if flags else []
        if nolog:
            flags.append('nolog')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='getacnonop', params=params, trs_ip=ne, flags=flags)

    def set_backhaul_params_with_parameter_file(self, parameter_file, timeout='5min', flags=None, **kwargs):
        """
        Set AC non-operator owned backhaul parameters.

        :param string  parameter_file: Full path of the parameter file containing updated parameters with parameter file

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        parameter_file = parameter_file.strip() if parameter_file else None
        params = {'parameterfile': parameter_file, 'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = flags.replace(' ', '').split(',') if flags else []
        if nolog:
            flags.append('nolog')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='setacnonop', params=params, trs_ip=ne, flags=flags)

    def set_backhaul_params_with_parameter(self, parameter, timeout='5min', flags=None, **kwargs):
        """
        Set AC non-operator owned backhaul parameters with parameters

        :param string  parameter: String that contains the list of updated parameters, e.g.
                                  _primaryiOMSIpAddress:192.168.21.4,_primaryiOMSFQDN:server1

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        parameter = '"{}"'.format(parameter.strip()) if parameter else None
        params = {'parameter': parameter, 'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = flags.replace(' ', '').split(',') if flags else []
        if nolog:
            flags.append('nolog')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='setacnonop', params=params, trs_ip=ne, flags=flags)
